"use client";
/* Server, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Server(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("server"); }, []);
  return React.createElement("piix-sprite", { "name": "server", ...piixAttrs(props) });
}

export default Server;
